    const path = groupWithUpdate
      .append('path')
      .merge(groupWithData.select('path.arc'));

    path
      .attr('class', 'arc')
      .attr('d', createArc)
      .attr('fill', (d, i) => {
        const { data } = d;
        return data.color;
      });
