import React, { useState } from 'react';
import { Redirect } from 'react-router-dom';
import { useHistory } from 'react-router-dom';
import { checkUser, checkAuth } from '../../services/user.service';
import { authLevelRedirect } from '../../utils/authUtils';
import { Typography, Button, FormControl, Box, TextField } from '@mui/material';

import useAuth from '../../hooks/useAuth';
import '../../sass/AdminLogin.scss';

/** At the moment only users with the 'admin' accessLevel can login
 * and see the dashboard
 **/
const Auth = () => {
  const LOG_IN = 'LOG_IN';
  const ADMIN = 'admin';
  const USER = 'user';
  const pattern = /\b[a-z0-9._]+@[a-z0-9.-]+\.[a-z]{2,4}\b/i;

  const history = useHistory();
  const { auth } = useAuth();

  const [email, setEmail] = useState('');
  const [isDisabled, setIsDisabled] = useState(true);
  const [isError, setIsError] = useState(false);
  const [errorMessage, setErrorMessage] = useState(' ');

  const validateEmail = () => {
    if (email.search(pattern) !== -1) {
      setIsDisabled(false);
      return true;
    } else {
      setIsDisabled(true);
      showError('Please enter a valid email address');
      return false;
    }
  };

  const showError = (message) => {
    setIsError(true);
    setErrorMessage(message);
  };

  const handleLogin = async (e) => {
    e.preventDefault();

    const isEmailValid = validateEmail();

    if (isEmailValid) {
      const userData = await checkUser(email, LOG_IN);
      if (userData) {
        if (
          userData.user.accessLevel !== ADMIN &&
          userData.user.accessLevel === USER &&
          userData.user.managedProjects.length === 0
        ) {
          showError(
            "You don't have the correct access level to view the dashboard"
          );
          return;
        }

        const isAuth = await checkAuth(email, LOG_IN);
        if (isAuth) {
          history.push('/emailsent');
        } else {
          showError(
            'We don’t recognize your email address. Please, create an account.'
          );
        }
      } else {
        showError(
          'We don’t recognize your email address. Please, create an account.'
        );
      }
    }
  };

  function handleInputChange(e) {
    const inputValue = e.currentTarget.value.toString();
    validateEmail();
    if (!inputValue) {
      setIsDisabled(true);
      showError('Please enter a valid email address');
    } else {
      setIsDisabled(false);
      setIsError(false);
      setEmail(e.currentTarget.value.toString());
    }
  }

  // This allows users who are not admin, but are allowed to manage projects, to login
  let loginRedirect = '';
  if (auth?.user) {
    loginRedirect = authLevelRedirect(auth.user);
  }

  return auth?.user ? (
    <Redirect to={loginRedirect} />
  ) : (
    <div className="flex-container">
      <div className="adminlogin-container">
        <div className="adminlogin-headers">
          <Typography variant="h3" sx={{ fontSize: '2.8em' }}>
            Welcome Back!
          </Typography>
        </div>
        <form
          onSubmit={handleLogin}
          className="form-check-in"
          autoComplete="off"
        >
          <FormControl>
            <div className="form-row">
              <div className="form-input-text">
                <Box className="form-row">
                  <Box className="form-input-text">
                    <TextField
                      label="Enter your email address:"
                      type="email"
                      name="email"
                      placeholder="Email Address"
                      required="required"
                      onChange={handleInputChange}
                      aria-label="Email Address"
                      data-test="input-email"
                      autoComplete="email"
                    />
                  </Box>
                </Box>
              </div>
            </div>
          </FormControl>
        </form>

        <div
          className="adminlogin-warning"
          style={{ visibility: isError ? 'visible' : 'hidden' }}
        >
          {errorMessage}
        </div>

        <div className="form-input-button">
          <Button
            type="submit"
            onClick={handleLogin}
            className="login-button"
            data-test="login-btn"
            disabled={isDisabled}
            sx={{ color: 'black' }}
          >
            LOGIN
          </Button>
        </div>
      </div>
    </div>
  );
};

export default Auth;

import React, { useState, useEffect } from 'react';
import { Redirect } from 'react-router-dom';
import { isValidToken } from '../../services/user.service';
import { authLevelRedirect } from '../../utils/authUtils';

import '../../sass/MagicLink.scss';
import useAuth from '../../hooks/useAuth';

const HandleAuth = (props) => {
  const { auth, refreshAuth } = useAuth();
  const [isMagicLinkValid, setMagicLink] = useState(null);
  const [isLoaded, setIsLoaded] = useState(false);

  // Step 1: Validate token from query string
  useEffect(() => {
    const search = props.location.search;
    const params = new URLSearchParams(search);
    const api_token = params.get('token');

    if (!api_token) return;
    isValidToken(api_token).then((isValid) => {
      setMagicLink(isValid);
    });
  }, [props.location.search]);

  // Step 2: Refresh user auth (requires valid Magic Link)
  useEffect(() => {
    if (!isMagicLinkValid) return;
    if (!auth?.isError) return;

    refreshAuth();
  }, [isMagicLinkValid, refreshAuth, auth]);

  // Step 3: Set IsLoaded value to render Component
  useEffect(() => {
    if (!isMagicLinkValid) {
      setIsLoaded(true);
      return;
    }

    if (!auth || auth.isError) return;

    setIsLoaded(true);
  }, [isMagicLinkValid, setIsLoaded, auth]);

  if (!isLoaded) return <div>Loading...</div>;

  const Delayed = ({ children, waitBeforeShow = 500 }) => {
    const [isShown, setIsShown] = useState(false);
    useEffect(() => {
      const timer = setTimeout(() => {
        setIsShown(true);
      }, waitBeforeShow);

      return () => clearTimeout(timer);
    }, [waitBeforeShow]);

    return isShown ? children : null;
  };

  let loginRedirect = '';

  if (auth?.user) {
    loginRedirect = authLevelRedirect(auth.user);
  }

  return (
    <div className="flex-container">
      <Delayed waitBeforeShow={1000}>
        <div>Sorry, the link is not valid anymore.</div>
      </Delayed>
      {auth?.user && <Redirect to={loginRedirect} /> /* Redirect to /welcome */}
    </div>
  );
};

export default HandleAuth;

