import React, { createContext, useState, useEffect } from 'react';
import { REACT_APP_CUSTOM_REQUEST_HEADER as headerToSend } from '../utils/globalSettings';
import * as authApi from '../api/auth';
import { useHistory } from 'react-router-dom';

export const AuthContext = createContext();

export const AuthProvider = ({ children }) => {
  const [auth, setAuth] = useState();
  const history = useHistory();

  useEffect(() => {
    refreshAuth();
  }, []);

  const refreshAuth = async () => {
    const userAuth = await fetchAuth();
    setAuth(userAuth);
  };

  const logout = async () => {
    const res = await authApi.fetchLogout();

    if (!res.ok) {
      throw new Error(res.statusText);
    }

    history.push('/');
    setAuth(null);
  };

  return (
    <AuthContext.Provider value={{ auth, refreshAuth, logout }}>
      {children}
    </AuthContext.Provider>
  );
};

const fetchAuth = async () => {
  const request = {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'x-customrequired-header': headerToSend,
    },
  };

  try {
    const response = await fetch('/api/auth/me', request);
    if (response.status !== 200)
      return { user: null, isAdmin: false, isError: true };

    const user = await response.json();
    return { user, isAdmin: (user.accessLevel === 'admin' || user.accessLevel === 'superadmin'), isError: false };
  } catch (error) {
    // this should never be hit...
    console.error('fetchAuth - error', error);
  }
};

import React, { createContext, useContext, useState } from 'react';
import Snackbar from '@mui/material/Snackbar';
import Alert from '@mui/material/Alert';
import Slide from '@mui/material/Slide';

const SnackbarContext = createContext();

export const useSnackbar = () => useContext(SnackbarContext);

export const SnackbarProvider = ({ children }) => {
  const [snackbarState, setSnackbarState] = useState({
    open: false,
    message: '',
    severity: '',
  });

  const showSnackbar = (message, severity) => {
    setSnackbarState({ open: true, message, severity });
  };

  const hideSnackbar = () => {
    setSnackbarState({ ...snackbarState, open: false });
  };

  return (
    <SnackbarContext.Provider value={{ showSnackbar, hideSnackbar }}>
      {children}
      <Snackbar
        open={snackbarState.open}
        autoHideDuration={7000}
        onClose={hideSnackbar}
        anchorOrigin={{
          vertical: 'bottom',
          horizontal: 'right',
        }}
        TransitionComponent={Slide}
      >
        <Alert
          onClose={hideSnackbar}
          severity={snackbarState.severity}
          sx={{width: '100%'}}
        >
          {snackbarState.message}
        </Alert>
      </Snackbar>
    </SnackbarContext.Provider>
  );
};

