import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import moment from 'moment';
import { REACT_APP_CUSTOM_REQUEST_HEADER as headerToSend} from '../utils/globalSettings';

import '../sass/Event.scss';

const Event = (props) => {
  const [isLoading, setIsLoading] = useState(false);
  const [event, setEvent] = useState([]);
  const [isCheckInReady, setIsCheckInReady] = useState();

  // eslint-disable-next-line
  async function setCheckInReady(e) {
    e.preventDefault();

    try {
      await fetch(`/api/events/${props.match.params.id}`, {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          'x-customrequired-header': headerToSend,
        },
      }).then((response) => {
        if (response.ok) {
          setEvent(event);
          setIsCheckInReady(!isCheckInReady);
        }
      });
    } catch (error) {
      setIsLoading(!isLoading);
    }
  }

  useEffect(() => {
    async function fetchEvent() {
      try {
        const res = await fetch(`/api/events/${props.match.params.id}`, {
          headers: {
            'x-customrequired-header': headerToSend,
          },
        });
        const resJson = await res.json();

        setEvent(resJson);
        setIsCheckInReady(resJson.checkInReady);
      } catch (error) {
        console.log(error);
      }
    }

    fetchEvent();
  }, [isLoading, isCheckInReady, props.match.params.id]);

  return (
    <div className="flex-container">
      <div className="event-container">
        {event && event.location ? (
          <div className="event-headers">
            <h4>{event.name}</h4>
            <p>{moment(event.date).format('dddd, MMMM D, YYYY @ h:mm a')}</p>
            <p>{event.location.city}</p>
            <p>{event.location.state}</p>
            {event.project &&
              <Link
                to={`/project/${event.project._id}`}
                className="create-form-button"
                style={{
                  width: '140px',
                  display: 'block',
                  margin: '0 auto 10px',
                  textAlign: 'center',
                  padding: '10px 0',
                }}
              >
                Edit Event
              </Link>
            }
          </div>
        ) : (
          <div>Loading...</div>
        )}

        <div>
          <p>
            <Link to="/events">
              <strong>Back to Events</strong>
            </Link>
          </p>
        </div>
      </div>
    </div>
  );
};

